class Boeing {
}

class Airplane {
  + Model : string
  + Options : string
  + Customizations : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + NegotiatedPrice : float
  + DeliveryDate : date
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
}

class Salesperson {
}

Employee "1" -- "0..*" Salesperson
Salesperson "1" -- "0..*" Contract
Contract "1" -- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "1" -- "0..*" Contract
Airline "0..1" o-- "0..*" Airline : daughter

Salesperson --|> Employee

@enduml

